ENTITY adp1d2 IS
 GENERIC
 (
  tpd_a_s          : VitalDelayType01 := (0 ps, 0 ps);
  tpd_b_p          : VitalDelayType01 := (0 ps, 0 ps);
  tpd_b_s          : VitalDelayType01 := (0 ps, 0 ps);
  tpd_ci_co        : VitalDelayType01 := (0 ps, 0 ps);
  tpd_ci_s         : VitalDelayType01 := (0 ps, 0 ps);
  tpd_a_co         : VitalDelayType01 := (0 ps, 0 ps);
  tpd_b_co         : VitalDelayType01 := (0 ps, 0 ps);
  tpd_a_p          : VitalDelayType01 := (0 ps, 0 ps);
  tipd_a        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_b        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_ci       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  TimingChecksOn : Boolean    := TRUE;
  XOn            : Boolean    := TRUE;
  MsgOn          : Boolean    := TRUE;
  InstancePath   : string     := ""
 );
 PORT
 (
  a          : IN         std_ulogic;
  b          : IN         std_ulogic;
  ci         : IN         std_ulogic;
  s          : OUT        std_ulogic;
  p          : OUT        std_ulogic;
  co         : OUT        std_ulogic
 );
ATTRIBUTE VITAL_LEVEL0 OF adp1d2 : ENTITY IS TRUE;
END adp1d2;

ARCHITECTURE behavioral OF adp1d2 IS

ATTRIBUTE VITAL_LEVEL1 OF behavioral : ARCHITECTURE IS TRUE;

SIGNAL a_ipd           : std_ulogic :='X';
SIGNAL b_ipd           : std_ulogic :='X';
SIGNAL ci_ipd          : std_ulogic :='X';

BEGIN

WIREDELAY : BLOCK
BEGIN
  VitalWireDelay ( a_ipd, a, tipd_a );
  VitalWireDelay ( b_ipd, b, tipd_b );
  VitalWireDelay ( ci_ipd, ci, tipd_ci );
END BLOCK;

VITALBehavior : PROCESS (a_ipd,b_ipd,ci_ipd)
VARIABLE s_GlitchData : VitalGlitchDataType;
VARIABLE p_GlitchData : VitalGlitchDataType;
VARIABLE co_GlitchData : VitalGlitchDataType;
VARIABLE s_zd : std_ulogic;
VARIABLE p_zd : std_ulogic;
VARIABLE co_zd : std_ulogic;

BEGIN
-------------------------
-- Functionality Section 
-------------------------


  s_zd := VitalXOR((ci_ipd, b_ipd, a_ipd));
  p_zd := VitalOR2(VitalAND2(b_ipd,VitalINV(a_ipd)),VitalAND2(VitalINV(b_ipd),a_ipd));
  co_zd := VitalOR2(VitalAND2(ci_ipd,VitalOR2(b_ipd,a_ipd)),VitalAND2(b_ipd,a_ipd));


--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (s, s_GlitchData, "s", s_zd,
 Paths=>(0=>(a_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_a_s),TRUE),
 1=>(b_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_b_s),TRUE),
 2=>(ci_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_ci_s),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (p, p_GlitchData, "p", p_zd,
 Paths=>(0=>(b_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_b_p),TRUE),
 1=>(a_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_a_p),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (co, co_GlitchData, "co", co_zd,
 Paths=>(0=>(ci_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_ci_co),TRUE),
 1=>(a_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_a_co),TRUE),
 2=>(b_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_b_co),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


