-- ****************************************************
-- (C) Copyright 1999 Avant! Corp. All rights reserved.
-- AVANT! Vital Models.
-- ****************************************************
-- Description     :  REPEATER CELL
-- Library         : cb18os120
-- Master version  : Rev. main.2
--
--

LIBRARY ieee;                  USE ieee.std_logic_1164.ALL;
                               USE ieee.vital_timing.ALL;
                               USE ieee.vital_primitives.ALL;


ENTITY bh01d1 IS
 GENERIC
 (
  tipd_i        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  TimingChecksOn : Boolean    := TRUE;
  XOn            : Boolean    := TRUE;
  MsgOn          : Boolean    := TRUE;
  InstancePath   : string     := ""
 );

   PORT (
        I    : INOUT std_ulogic := 'Z'  -- bidirectional pin
        );

ATTRIBUTE VITAL_LEVEL0 OF bh01d1:ENTITY IS TRUE;

END bh01d1;

ARCHITECTURE behavioral OF bh01d1 IS

  ATTRIBUTE VITAL_LEVEL0 OF behavioral : ARCHITECTURE IS TRUE;

BEGIN
-------------------------
-- Functionality Section 
-------------------------


  proc_bh01d1: PROCESS (I)

  BEGIN

    if I /= 'Z' then
      if (I = '1' or I = 'H') then
        I <= 'H';
      elsif (I = '0' or I = 'L') then
        I <= 'L';
      elsif (I = 'X') then
        I <= 'W';
      end if;
    end if;

  END PROCESS;

END behavioral;


