  thold_d_cpn_posedge_negedge       : VitalDelayType := 0 ps;
  thold_cdn_cpn_posedge_negedge     : VitalDelayType := 0 ps;
  tpw_cpn_negedge                   : VitalDelayType := 0 ps;
  tpw_cpn_posedge                   : VitalDelayType := 0 ps;
  tpw_cdn_negedge                   : VitalDelayType := 0 ps;
