  ticd_cpn      : VitalDelayType := 0 ps;
  tisd_cdn_cpn  : VitalDelayType := 0 ps;
  tisd_d_cpn    : VitalDelayType := 0 ps;
  tisd_enn_cpn  : VitalDelayType := 0 ps;
