VARIABLE tpw_cp   : VitalPeriodDataType;
VARIABLE pw_cdn    : std_ulogic := '0';
VARIABLE tpw_cdn   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => enn_dly,
  TestSignalName => "enn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_enn_cp_posedge_posedge,
  SetupLow      => tsetup_enn_cp_negedge_posedge,
  HoldHigh      => thold_enn_cp_negedge_posedge,
  HoldLow       => thold_enn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /DECRQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_enn_cp,
  Violation     => suh_enn_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => d_dly,
  TestSignalName => "d",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_d_cp_posedge_posedge,
  SetupLow      => tsetup_d_cp_negedge_posedge,
  HoldHigh      => thold_d_cp_negedge_posedge,
  HoldLow       => thold_d_cp_posedge_posedge,
  CheckEnabled  => (To_X01(enn_dly)='0') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /DECRQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_d_cp,
  Violation     => suh_d_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => cdn_dly,
  TestSignalName => "cdn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => trecovery_cdn_cp_posedge_posedge,
  HoldLow       => thold_cdn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(enn_dly)='0'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /DECRQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_cdn_cp,
  Violation     => suh_cdn_cp
 );
 VitalPeriodPulseCheck (
  TestSignal     => cp_dly,
  TestSignalName => "cp",
  PulseWidthHigh => tpw_cp_posedge,
  PulseWidthLow  => tpw_cp_negedge,
  PeriodData     => tpw_cp,
  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /DECRQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(enn_dly)='0') and (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /DECRQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => TRUE
  );
END IF;

violation := suh_enn_cp OR suh_d_cp OR suh_cdn_cp OR pw_cp OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,enn_dly,cp_dly,d_dly,violation),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(cdn_dly)/='0') and (To_X01(enn_dly)='0')),
 1=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


