-- sdn  cp  enn  d  violation  q  q
 (  '-',  '-',  '-',  '-',  'X',  '-',  'X'),
 (  '0',  '-',  '-',  '-',  '-',  '-',  '1'),
 (  '1',  '/',  '0',  '0',  '-',  '-',  '0'),
