ALIAS qn_zd : std_ulogic IS Res(0);
ALIAS q_zd : std_ulogic IS Res(1);

CONSTANT StateTab : VitalStateTableType (1 TO 17, 1 TO 9) := (
-- sdn  cdn  cpn  d  violation  qn  q  qn  q
 (  '-',  '-',  '-',  '-',  'X',  '-',  '-',  'X',  'X'),
 (  '0',  '0',  '-',  '-',  '-',  '-',  '-',  '0',  '0'),
