ALIAS qn_zd : std_ulogic IS Res(0);
ALIAS q_zd : std_ulogic IS Res(1);

CONSTANT StateTab : VitalStateTableType (1 TO 10, 1 TO 8) := (
-- sdn  cp  d  violation  qn  q  qn  q
 (  '-',  '-',  '-',  'X',  '-',  '-',  'X',  'X'),
 (  '0',  '-',  '-',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  '/',  '0',  '-',  '-',  '-',  '1',  '0'),
 (  '1',  '/',  '1',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  '0',  '-',  '-',  '-',  '-',  'S',  'S'),
 (  '1',  'S',  '-',  '-',  '-',  '-',  'S',  'S'),
 (  'B',  'B',  'B',  '-',  'B',  'B',  'S',  'S'),
 (  'X',  '/',  '1',  '-',  '-',  '-',  '0',  '1'),
 (  'X',  '0',  '-',  '-',  '0',  '1',  'S',  'S'),
 (  'X',  'S',  '-',  '-',  '0',  '1',  'S',  'S')
);
