VitalStateTable ( StateTable => StateTab,
                      DataIn => (sdn_dly,cp_dly,d_dly,violation),
                   NumStates => 2,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (qn, qn_GlitchData, "qn", qn_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_qn),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_qn),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


