  tipd_i        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_en       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
