SIGNAL en_ipd          : std_ulogic :='X';

BEGIN

WIREDELAY : BLOCK
BEGIN
  VitalWireDelay ( i_ipd, i, tipd_i );
  VitalWireDelay ( en_ipd, en, tipd_en );
END BLOCK;

VITALBehavior : PROCESS (i_ipd,en_ipd)
VARIABLE zn_GlitchData : VitalGlitchDataType;
VARIABLE Prv : std_logic_vector(0 TO 1);
VARIABLE Res : std_logic_vector(0 TO 0) := (OTHERS=>'X');
