-- en  i    -  zn
 (  '0',  '1',  '-',  '0'),
 (  '0',  '0',  '-',  '1'),
 (  '1',  '-',  '-',  'Z')
);

BEGIN
-------------------------
-- Functionality Section 
-------------------------




VitalStateTable ( StateTable => StateTab,
                      DataIn => (en_ipd,i_ipd),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (zn, zn_GlitchData, "zn", zn_zd,
 Paths=>(0=>(en_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_en_zn),TRUE),
 1=>(i_ipd'LAST_EVENT,VitalExtendToFillDelay(tpd_i_zn),TRUE)),
