 (  '1',  '1',  '/',  '0',  '1',  '-',  '1',  '1',  '0',  '0'),
 (  '1',  '1',  '/',  '1',  '1',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  '1',  '-',  '1',  '0',  '-',  '-',  '-',  'S',  'S'),
 (  '1',  '1',  '0',  '-',  '-',  '-',  '-',  '-',  'S',  'S'),
 (  '1',  '1',  'S',  '-',  '-',  '-',  '-',  '-',  'S',  'S'),
 (  'B',  'B',  'B',  'B',  'B',  '-',  'B',  'B',  'S',  'S'),
 (  '0',  'X',  '-',  '-',  '-',  '-',  '-',  '-',  'X',  '0'),
 (  'X',  '0',  '-',  '-',  '-',  '-',  '-',  '-',  '0',  'X'),
 (  'X',  '1',  '/',  '0',  '0',  '-',  '-',  '-',  '1',  '0'),
 (  'X',  '1',  '/',  '0',  '1',  '-',  '0',  '0',  '1',  'X'),
 (  'X',  '1',  '/',  '0',  '1',  '-',  '0',  '1',  '1',  '0'),
 (  'X',  '1',  '/',  '0',  '1',  '-',  '1',  '1',  'X',  '0'),
 (  'X',  '1',  '-',  '1',  '0',  '-',  '1',  '0',  'S',  'S'),
 (  'X',  '1',  '0',  '-',  '-',  '-',  '1',  '0',  'S',  'S'),
 (  'X',  '1',  'S',  '-',  '-',  '-',  '1',  '0',  'S',  'S'),
 (  '1',  'X',  '/',  '0',  '1',  '-',  '0',  '0',  'X',  '1'),
 (  '1',  'X',  '/',  '0',  '1',  '-',  '1',  '0',  '0',  '1'),
 (  '1',  'X',  '/',  '0',  '1',  '-',  '1',  '1',  '0',  'X'),
 (  '1',  'X',  '/',  '1',  '1',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  'X',  '-',  '1',  '0',  '-',  '0',  '1',  'S',  'S'),
 (  '1',  'X',  '0',  '-',  '-',  '-',  '0',  '1',  'S',  'S'),
 (  '1',  'X',  'S',  '-',  '-',  '-',  '0',  '1',  'S',  'S'),
 (  '1',  '1',  '/',  '0',  'X',  '-',  '0',  '0',  '1',  'X'),
 (  '1',  '1',  '/',  '0',  'X',  '-',  '0',  '1',  '1',  '0'),
 (  '1',  '1',  '/',  '0',  'X',  '-',  '1',  '1',  'X',  '0'),
 (  '1',  '1',  '/',  'X',  '0',  '-',  '1',  '0',  'S',  'S'),
 (  '1',  '1',  '/',  '0',  '1',  '-',  'X',  '0',  'X',  '1'),
 (  '1',  '1',  '/',  '0',  '1',  '-',  '0',  'X',  '1',  'X'),
 (  '1',  '1',  '/',  'X',  '1',  '-',  '0',  '0',  'X',  '1'),
 (  '1',  '1',  '/',  '0',  '1',  '-',  '1',  'X',  '0',  'X'),
 (  '1',  '1',  '/',  'X',  '1',  '-',  '1',  '0',  '0',  '1'),
 (  '1',  '1',  '/',  '0',  '1',  '-',  'X',  '1',  'X',  '0'),
 (  '1',  '1',  '/',  'X',  '1',  '-',  '1',  '1',  '0',  'X'),
 (  '1',  '1',  '/',  '1',  'X',  '-',  '0',  '1',  'S',  'S')
);
VARIABLE violation : std_ulogic := '0';
VARIABLE suh_kz_cp  : std_ulogic := '0';
VARIABLE tsuh_kz_cp : VitalTimingDataType;
VARIABLE suh_j_cp  : std_ulogic := '0';
VARIABLE tsuh_j_cp : VitalTimingDataType;
VARIABLE suh_sdn_cp  : std_ulogic := '0';
VARIABLE tsuh_sdn_cp : VitalTimingDataType;
VARIABLE suh_cdn_cp  : std_ulogic := '0';
VARIABLE tsuh_cdn_cp : VitalTimingDataType;
VARIABLE pw_cp    : std_ulogic := '0';
VARIABLE tpw_cp   : VitalPeriodDataType;
VARIABLE pw_sdn    : std_ulogic := '0';
VARIABLE tpw_sdn   : VitalPeriodDataType;
VARIABLE pw_cdn    : std_ulogic := '0';
VARIABLE tpw_cdn   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => kz_dly,
  TestSignalName => "kz",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_kz_cp_posedge_posedge,
  SetupLow      => tsetup_kz_cp_negedge_posedge,
  HoldHigh      => thold_kz_cp_negedge_posedge,
  HoldLow       => thold_kz_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /JKBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_kz_cp,
  Violation     => suh_kz_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => j_dly,
  TestSignalName => "j",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_j_cp_posedge_posedge,
  SetupLow      => tsetup_j_cp_negedge_posedge,
  HoldHigh      => thold_j_cp_negedge_posedge,
  HoldLow       => thold_j_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /JKBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_j_cp,
  Violation     => suh_j_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => sdn_dly,
  TestSignalName => "sdn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => trecovery_sdn_cp_posedge_posedge,
  HoldLow       => thold_sdn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /JKBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sdn_cp,
  Violation     => suh_sdn_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => cdn_dly,
  TestSignalName => "cdn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => trecovery_cdn_cp_posedge_posedge,
  HoldLow       => thold_cdn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /JKBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_cdn_cp,
  Violation     => suh_cdn_cp
 );
 VitalPeriodPulseCheck (
  TestSignal     => cp_dly,
  TestSignalName => "cp",
  PulseWidthHigh => tpw_cp_posedge,
  PulseWidthLow  => tpw_cp_negedge,
  PeriodData     => tpw_cp,
  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /JKBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => sdn_dly,
  TestSignalName => "sdn",
  PulseWidthLow  => tpw_sdn_negedge,
  PeriodData     => tpw_sdn,
  Violation      => pw_sdn,
  HeaderMsg      => InstancePath & " /JKBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /JKBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1')
  );
END IF;

violation := suh_kz_cp OR suh_j_cp OR suh_sdn_cp OR suh_cdn_cp OR pw_cp OR pw_sdn OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,sdn_dly,cp_dly,kz_dly,j_dly,violation),
                   NumStates => 2,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),TRUE),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_q),(To_X01(cdn_dly)/='0')),
 2=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(sdn_dly)/='0') and (To_X01(cdn_dly)/='0'))),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (qn, qn_GlitchData, "qn", qn_zd,
 Paths=>(0=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_qn),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_qn),TRUE),
 2=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_qn),(To_X01(sdn_dly)/='0') and (To_X01(cdn_dly)/='0'))),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


