  Violation      => pw_sdn,
  HeaderMsg      => InstancePath & " /LABHB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /LABHB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1')
  );
END IF;

violation := suh_d_e OR suh_sdn_e OR suh_cdn_e OR pw_e OR pw_sdn OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,sdn_dly,e_dly,d_dly,violation),
                   NumStates => 2,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_q),TRUE),
 2=>(e_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_e_q),(To_X01(cdn_dly)/='0') and (To_X01(sdn_dly)/='0')),
 3=>(d_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_d_q),(To_X01(e_dly)/='0') and (To_X01(cdn_dly)/='0') and (To_X01(sdn_dly)/='0'))),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (qn, qn_GlitchData, "qn", qn_zd,
 Paths=>(0=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_qn),(To_X01(cdn_dly)/='0')),
 1=>(e_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_e_qn),(To_X01(cdn_dly)/='0') and (To_X01(sdn_dly)/='0')),
 2=>(d_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_d_qn),(To_X01(e_dly)/='0') and (To_X01(cdn_dly)/='0') and (To_X01(sdn_dly)/='0')),
 3=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_qn),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


