  tpd_e_q            : VitalDelayType01 := (0 ps, 0 ps);
  tpd_e_qn           : VitalDelayType01 := (0 ps, 0 ps);
  tpd_d_q  : VitalDelayType01 := (0 ps, 0 ps);
  tpd_d_qn : VitalDelayType01 := (0 ps, 0 ps);
  tpd_cdn_qn                              : VitalDelayType01 := (0 ps, 0 ps);
  tsetup_d_e_posedge_negedge              : VitalDelayType := 0 ps;
  tsetup_d_e_negedge_negedge              : VitalDelayType := 0 ps;
  trecovery_sdn_e_posedge_negedge         : VitalDelayType := 0 ps;
  trecovery_cdn_e_posedge_negedge         : VitalDelayType := 140 ps;
  thold_d_e_negedge_negedge               : VitalDelayType := 0 ps;
  thold_d_e_posedge_negedge               : VitalDelayType := 0 ps;
  thold_sdn_e_posedge_negedge             : VitalDelayType := 0 ps;
  thold_cdn_e_posedge_negedge             : VitalDelayType := 0 ps;
  tpw_e_posedge                           : VitalDelayType := 0 ps;
  tpw_sdn_negedge                         : VitalDelayType := 0 ps;
  tpw_cdn_negedge                         : VitalDelayType := 0 ps;
  tipd_e        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_d        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_cdn      : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_sdn      : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  ticd_e        : VitalDelayType := 0 ps;
  tisd_d_e      : VitalDelayType := 0 ps;
  tisd_cdn_e    : VitalDelayType := 0 ps;
  tisd_sdn_e    : VitalDelayType := 0 ps;
  TimingChecksOn : Boolean    := TRUE;
  XOn            : Boolean    := TRUE;
  MsgOn          : Boolean    := TRUE;
  InstancePath   : string     := ""
 );
 PORT
 (
  e          : IN         std_ulogic;
  d          : IN         std_ulogic;
  cdn        : IN         std_ulogic;
  sdn        : IN         std_ulogic;
  q          : OUT        std_ulogic;
