SIGNAL d_dly           : std_ulogic :='X';
SIGNAL cdn_dly         : std_ulogic :='X';

BEGIN

WIREDELAY : BLOCK
BEGIN
  VitalWireDelay ( e_ipd, e, tipd_e );
  VitalWireDelay ( d_ipd, d, tipd_d );
  VitalWireDelay ( cdn_ipd, cdn, tipd_cdn );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
  VitalSignalDelay ( e_dly, e_ipd, ticd_e );
  VitalSignalDelay ( d_dly, d_ipd, tisd_d_e );
  VitalSignalDelay ( cdn_dly, cdn_ipd, tisd_cdn_e );
END BLOCK;

VITALBehavior : PROCESS (e_dly,d_dly,cdn_dly)
VARIABLE q_GlitchData : VitalGlitchDataType;
VARIABLE Prv : std_logic_vector(0 TO 3);
VARIABLE Res : std_logic_vector(0 TO 0) := (OTHERS=>'X');
ALIAS q_zd : std_ulogic IS Res(0);

CONSTANT StateTab : VitalStateTableType (1 TO 10, 1 TO 6) := (
-- cdn  e  d  violation  q  q
 (  '-',  '-',  '-',  'X',  '-',  'X'),
 (  '0',  '-',  '-',  '-',  '-',  '0'),
 (  '1',  '1',  '0',  '-',  '-',  '0'),
 (  '1',  '1',  '1',  '-',  '-',  '1'),
 (  '1',  '0',  '-',  '-',  '-',  'S'),
 (  'B',  'B',  'B',  '-',  'B',  'S'),
 (  'X',  '1',  '0',  '-',  '-',  '0'),
 (  'X',  '0',  '-',  '-',  '0',  'S'),
 (  '1',  'X',  '0',  '-',  '0',  'S'),
 (  '1',  'X',  '1',  '-',  '1',  'S')
);
VARIABLE violation : std_ulogic := '0';
VARIABLE suh_d_e  : std_ulogic := '0';
VARIABLE tsuh_d_e : VitalTimingDataType;
VARIABLE suh_cdn_e  : std_ulogic := '0';
VARIABLE tsuh_cdn_e : VitalTimingDataType;
VARIABLE pw_e    : std_ulogic := '0';
VARIABLE tpw_e   : VitalPeriodDataType;
VARIABLE pw_cdn    : std_ulogic := '0';
VARIABLE tpw_cdn   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => d_dly,
  TestSignalName => "d",
  RefSignal     => e_dly,
  RefSignalName => "e",
  SetupHigh     => tsetup_d_e_posedge_negedge,
  SetupLow      => tsetup_d_e_negedge_negedge,
  HoldHigh      => thold_d_e_negedge_negedge,
  HoldLow       => thold_d_e_posedge_negedge,
  CheckEnabled  => (To_X01(cdn_dly)='1'),
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /LACHQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_d_e,
  Violation     => suh_d_e
 );
 VitalSetupHoldCheck (
  TestSignal    => cdn_dly,
  TestSignalName => "cdn",
  RefSignal     => e_dly,
  RefSignalName => "e",
  SetupHigh     => trecovery_cdn_e_posedge_negedge,
  HoldLow       => thold_cdn_e_posedge_negedge,
  CheckEnabled  => TRUE,
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /LACHQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_cdn_e,
  Violation     => suh_cdn_e
 );
 VitalPeriodPulseCheck (
  TestSignal     => e_dly,
  TestSignalName => "e",
  PulseWidthHigh => tpw_e_posedge,
  PeriodData     => tpw_e,
  Violation      => pw_e,
  HeaderMsg      => InstancePath & " /LACHQ2",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /LACHQ2",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => TRUE
  );
END IF;

violation := suh_d_e OR suh_cdn_e OR pw_e OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,e_dly,d_dly,violation),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(e_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_e_q),(To_X01(cdn_dly)/='0')),
 1=>(d_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_d_q),(To_X01(e_dly)/='0') and (To_X01(cdn_dly)/='0')),
 2=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


