 (
  tpd_a3_zn        : VitalDelayType01 := (0 ps, 0 ps);
  tpd_a1_zn        : VitalDelayType01 := (0 ps, 0 ps);
  tpd_a2_zn        : VitalDelayType01 := (0 ps, 0 ps);
