  tipd_a3       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  TimingChecksOn : Boolean    := TRUE;
  XOn            : Boolean    := TRUE;
  MsgOn          : Boolean    := TRUE;
  InstancePath   : string     := ""
 );
 PORT
 (
  a1         : IN         std_ulogic;
  a2         : IN         std_ulogic;
  a3         : IN         std_ulogic;
  zn         : OUT        std_ulogic
 );
