 (  '1',  'X',  '/',  '0',  '1',  '-',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  'X',  '/',  '1',  '-',  '1',  '-',  '-',  '-',  '0',  '1'),
 (  '1',  'X',  '0',  '-',  '-',  '-',  '-',  '0',  '1',  'S',  'S'),
 (  '1',  'X',  'S',  '-',  '-',  '-',  '-',  '0',  '1',  'S',  'S'),
 (  '1',  '1',  '/',  'X',  '0',  '0',  '-',  '-',  '-',  '1',  '0'),
 (  '1',  '1',  '/',  'X',  '1',  '1',  '-',  '-',  '-',  '0',  '1')
);
VARIABLE violation : std_ulogic := '0';
VARIABLE suh_sd_cp  : std_ulogic := '0';
VARIABLE tsuh_sd_cp : VitalTimingDataType;
VARIABLE suh_sc_cp  : std_ulogic := '0';
VARIABLE tsuh_sc_cp : VitalTimingDataType;
VARIABLE suh_d_cp  : std_ulogic := '0';
VARIABLE tsuh_d_cp : VitalTimingDataType;
VARIABLE suh_sdn_cp  : std_ulogic := '0';
VARIABLE tsuh_sdn_cp : VitalTimingDataType;
VARIABLE suh_cdn_cp  : std_ulogic := '0';
VARIABLE tsuh_cdn_cp : VitalTimingDataType;
VARIABLE pw_cp    : std_ulogic := '0';
VARIABLE tpw_cp   : VitalPeriodDataType;
VARIABLE pw_sdn    : std_ulogic := '0';
VARIABLE tpw_sdn   : VitalPeriodDataType;
VARIABLE pw_cdn    : std_ulogic := '0';
VARIABLE tpw_cdn   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => sd_dly,
  TestSignalName => "sd",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sd_cp_posedge_posedge,
  SetupLow      => tsetup_sd_cp_negedge_posedge,
  HoldHigh      => thold_sd_cp_negedge_posedge,
  HoldLow       => thold_sd_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(sc_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sd_cp,
  Violation     => suh_sd_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => sc_dly,
  TestSignalName => "sc",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sc_cp_posedge_posedge,
  SetupLow      => tsetup_sc_cp_negedge_posedge,
  HoldHigh      => thold_sc_cp_negedge_posedge,
  HoldLow       => thold_sc_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sc_cp,
  Violation     => suh_sc_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => d_dly,
  TestSignalName => "d",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_d_cp_posedge_posedge,
  SetupLow      => tsetup_d_cp_negedge_posedge,
  HoldHigh      => thold_d_cp_negedge_posedge,
  HoldLow       => thold_d_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(sc_dly)='0') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_d_cp,
  Violation     => suh_d_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => sdn_dly,
  TestSignalName => "sdn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => trecovery_sdn_cp_posedge_posedge,
  HoldLow       => thold_sdn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sdn_cp,
  Violation     => suh_sdn_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => cdn_dly,
  TestSignalName => "cdn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => trecovery_cdn_cp_posedge_posedge,
  HoldLow       => thold_cdn_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_cdn_cp,
  Violation     => suh_cdn_cp
 );
 VitalPeriodPulseCheck (
  TestSignal     => cp_dly,
  TestSignalName => "cp",
  PulseWidthHigh => tpw_cp_posedge,
  PulseWidthLow  => tpw_cp_negedge,
  PeriodData     => tpw_cp,
  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /SDBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => sdn_dly,
  TestSignalName => "sdn",
  PulseWidthLow  => tpw_sdn_negedge,
  PeriodData     => tpw_sdn,
  Violation      => pw_sdn,
  HeaderMsg      => InstancePath & " /SDBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /SDBRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1')
  );
END IF;

violation := suh_sd_cp OR suh_sc_cp OR suh_d_cp OR suh_sdn_cp OR suh_cdn_cp OR pw_cp OR pw_sdn OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,sdn_dly,cp_dly,sc_dly,d_dly,sd_dly,violation),
                   NumStates => 2,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),TRUE),
 1=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(sdn_dly)/='0') and (To_X01(cdn_dly)/='0')),
 2=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_q),(To_X01(cdn_dly)/='0'))),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (qn, qn_GlitchData, "qn", qn_zd,
 Paths=>(0=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_qn),TRUE),
 1=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_qn),(To_X01(sdn_dly)/='0') and (To_X01(cdn_dly)/='0')),
 2=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_qn),(To_X01(sdn_dly)/='0'))),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


