  trecovery_cdn_cp_posedge_posedge : VitalDelayType := 0 ps;
  thold_sd_cp_negedge_posedge      : VitalDelayType := 0 ps;
  thold_sd_cp_posedge_posedge      : VitalDelayType := 0 ps;
  thold_sc_cp_negedge_posedge      : VitalDelayType := 0 ps;
  thold_sc_cp_posedge_posedge      : VitalDelayType := 0 ps;
  thold_d_cp_negedge_posedge       : VitalDelayType := 0 ps;
  thold_d_cp_posedge_posedge       : VitalDelayType := 0 ps;
  thold_sdn_cp_posedge_posedge     : VitalDelayType := 0 ps;
  thold_cdn_cp_posedge_posedge     : VitalDelayType := 0 ps;
  tpw_cp_posedge                   : VitalDelayType := 0 ps;
  tpw_cp_negedge                   : VitalDelayType := 0 ps;
  tpw_sdn_negedge                  : VitalDelayType := 0 ps;
  tpw_cdn_negedge                  : VitalDelayType := 0 ps;
  tipd_d        : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_sd       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_sc       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_cp       : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_sdn      : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tipd_cdn      : VitalDelayType01Z := (0 ps,0 ps,0 ps,0 ps,0 ps,0 ps);
  tisd_d_cp     : VitalDelayType := 0 ps;
  tisd_sd_cp    : VitalDelayType := 0 ps;
  tisd_sc_cp    : VitalDelayType := 0 ps;
  ticd_cp       : VitalDelayType := 0 ps;
  tisd_sdn_cp   : VitalDelayType := 0 ps;
  tisd_cdn_cp   : VitalDelayType := 0 ps;
  TimingChecksOn : Boolean    := TRUE;
  XOn            : Boolean    := TRUE;
  MsgOn          : Boolean    := TRUE;
  InstancePath   : string     := ""
 );
 PORT
 (
  d          : IN         std_ulogic;
  sd         : IN         std_ulogic;
  sc         : IN         std_ulogic;
  cp         : IN         std_ulogic;
  sdn        : IN         std_ulogic;
  cdn        : IN         std_ulogic;
  q          : OUT        std_ulogic;
  qn         : OUT        std_ulogic
 );
ATTRIBUTE VITAL_LEVEL0 OF sdbrb2 : ENTITY IS TRUE;
END sdbrb2;

ARCHITECTURE behavioral OF sdbrb2 IS

ATTRIBUTE VITAL_LEVEL1 OF behavioral : ARCHITECTURE IS TRUE;

SIGNAL d_ipd           : std_ulogic :='X';
SIGNAL sd_ipd          : std_ulogic :='X';
SIGNAL sc_ipd          : std_ulogic :='X';
SIGNAL cp_ipd          : std_ulogic :='X';
SIGNAL sdn_ipd         : std_ulogic :='X';
SIGNAL cdn_ipd         : std_ulogic :='X';
SIGNAL d_dly           : std_ulogic :='X';
SIGNAL sd_dly          : std_ulogic :='X';
SIGNAL sc_dly          : std_ulogic :='X';
SIGNAL cp_dly          : std_ulogic :='X';
SIGNAL sdn_dly         : std_ulogic :='X';
SIGNAL cdn_dly         : std_ulogic :='X';

BEGIN

WIREDELAY : BLOCK
BEGIN
  VitalWireDelay ( d_ipd, d, tipd_d );
  VitalWireDelay ( sd_ipd, sd, tipd_sd );
  VitalWireDelay ( sc_ipd, sc, tipd_sc );
  VitalWireDelay ( cp_ipd, cp, tipd_cp );
  VitalWireDelay ( sdn_ipd, sdn, tipd_sdn );
  VitalWireDelay ( cdn_ipd, cdn, tipd_cdn );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
  VitalSignalDelay ( d_dly, d_ipd, tisd_d_cp );
  VitalSignalDelay ( sd_dly, sd_ipd, tisd_sd_cp );
  VitalSignalDelay ( sc_dly, sc_ipd, tisd_sc_cp );
  VitalSignalDelay ( cp_dly, cp_ipd, ticd_cp );
  VitalSignalDelay ( sdn_dly, sdn_ipd, tisd_sdn_cp );
  VitalSignalDelay ( cdn_dly, cdn_ipd, tisd_cdn_cp );
END BLOCK;

VITALBehavior : PROCESS (d_dly,sd_dly,sc_dly,cp_dly,sdn_dly,cdn_dly)
VARIABLE q_GlitchData : VitalGlitchDataType;
VARIABLE qn_GlitchData : VitalGlitchDataType;
