VARIABLE Res : std_logic_vector(0 TO 1) := (OTHERS=>'X');
ALIAS qn_zd : std_ulogic IS Res(0);
ALIAS q_zd : std_ulogic IS Res(1);

CONSTANT StateTab : VitalStateTableType (1 TO 23, 1 TO 11) := (
-- cdn  sdn  cp  sc  d  sd  violation  qn  q  qn  q
 (  '-',  '-',  '-',  '-',  '-',  '-',  'X',  '-',  '-',  'X',  'X'),
 (  '0',  '0',  '-',  '-',  '-',  '-',  '-',  '-',  '-',  '0',  '0'),
 (  '0',  '1',  '-',  '-',  '-',  '-',  '-',  '-',  '-',  '1',  '0'),
