-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => sd_dly,
  TestSignalName => "sd",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sd_cp_posedge_posedge,
  SetupLow      => tsetup_sd_cp_negedge_posedge,
  HoldHigh      => thold_sd_cp_negedge_posedge,
  HoldLow       => thold_sd_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(sc_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SDBRB2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sd_cp,
  Violation     => suh_sd_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => sc_dly,
  TestSignalName => "sc",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sc_cp_posedge_posedge,
  SetupLow      => tsetup_sc_cp_negedge_posedge,
  HoldHigh      => thold_sc_cp_negedge_posedge,
  HoldLow       => thold_sc_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sdn_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '/',
