VARIABLE pw_cpn    : std_ulogic := '0';
VARIABLE tpw_cpn   : VitalPeriodDataType;
VARIABLE pw_cdn    : std_ulogic := '0';
VARIABLE tpw_cdn   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => sd_dly,
  TestSignalName => "sd",
  RefSignal     => cpn_dly,
  RefSignalName => "cpn",
  SetupHigh     => tsetup_sd_cpn_posedge_negedge,
  SetupLow      => tsetup_sd_cpn_negedge_negedge,
  HoldHigh      => thold_sd_cpn_negedge_negedge,
  HoldLow       => thold_sd_cpn_posedge_negedge,
  CheckEnabled  => (To_X01(sc_dly)='1') and (To_X01(cdn_dly)='1'),
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /SDCFQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sd_cpn,
  Violation     => suh_sd_cpn
 );
 VitalSetupHoldCheck (
  TestSignal    => sc_dly,
  TestSignalName => "sc",
  RefSignal     => cpn_dly,
  RefSignalName => "cpn",
  SetupHigh     => tsetup_sc_cpn_posedge_negedge,
  SetupLow      => tsetup_sc_cpn_negedge_negedge,
  HoldHigh      => thold_sc_cpn_negedge_negedge,
  HoldLow       => thold_sc_cpn_posedge_negedge,
  CheckEnabled  => (To_X01(cdn_dly)='1'),
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /SDCFQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sc_cpn,
  Violation     => suh_sc_cpn
 );
 VitalSetupHoldCheck (
  TestSignal    => d_dly,
  TestSignalName => "d",
  RefSignal     => cpn_dly,
  RefSignalName => "cpn",
  SetupHigh     => tsetup_d_cpn_posedge_negedge,
  SetupLow      => tsetup_d_cpn_negedge_negedge,
  HoldHigh      => thold_d_cpn_negedge_negedge,
  HoldLow       => thold_d_cpn_posedge_negedge,
  CheckEnabled  => (To_X01(sc_dly)='0') and (To_X01(cdn_dly)='1'),
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /SDCFQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_d_cpn,
  Violation     => suh_d_cpn
 );
 VitalSetupHoldCheck (
  TestSignal    => cdn_dly,
  TestSignalName => "cdn",
  RefSignal     => cpn_dly,
  RefSignalName => "cpn",
  SetupHigh     => trecovery_cdn_cpn_posedge_negedge,
  HoldLow       => thold_cdn_cpn_posedge_negedge,
  CheckEnabled  => TRUE,
  RefTransition => '\',
  HeaderMsg     => InstancePath & " /SDCFQ1",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_cdn_cpn,
  Violation     => suh_cdn_cpn
 );
 VitalPeriodPulseCheck (
  TestSignal     => cpn_dly,
  TestSignalName => "cpn",
  PulseWidthHigh => tpw_cpn_posedge,
  PulseWidthLow  => tpw_cpn_negedge,
  PeriodData     => tpw_cpn,
  Violation      => pw_cpn,
  HeaderMsg      => InstancePath & " /SDCFQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(cdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => cdn_dly,
  TestSignalName => "cdn",
  PulseWidthLow  => tpw_cdn_negedge,
  PeriodData     => tpw_cdn,
  Violation      => pw_cdn,
  HeaderMsg      => InstancePath & " /SDCFQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => TRUE
  );
END IF;

violation := suh_sd_cpn OR suh_sc_cpn OR suh_d_cpn OR suh_cdn_cpn OR pw_cpn OR pw_cdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cdn_dly,sc_dly,cpn_dly,sd_dly,d_dly,violation),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cpn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cpn_q),(To_X01(cdn_dly)/='0')),
 1=>(cdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cdn_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


