  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /SDPRB1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => sdn_dly,
