  );
END IF;

violation := suh_sd_cp OR suh_sc_cp OR suh_d_cp OR suh_sdn_cp OR pw_cp OR pw_sdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (sdn_dly,sc_dly,cp_dly,d_dly,sd_dly,violation),
