              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(sdn_dly)/='0')),
