 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
VitalPathDelay01Z (qn, qn_GlitchData, "qn", qn_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_qn),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_qn),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


