LIBRARY ieee;                  USE ieee.std_logic_1164.ALL;
                               USE ieee.vital_timing.ALL;
                               USE ieee.vital_primitives.ALL;

ENTITY secrq1 IS
 GENERIC
 (
  tpd_cp_q                : VitalDelayType01 := (0 ps, 0 ps);
  tpd_cdn_q                        : VitalDelayType01 := (0 ps, 0 ps);
  tsetup_sd_cp_posedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sd_cp_negedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sc_cp_posedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sc_cp_negedge_posedge     : VitalDelayType := 0 ps;
  tsetup_enn_cp_posedge_posedge    : VitalDelayType := 0 ps;
  tsetup_enn_cp_negedge_posedge    : VitalDelayType := 0 ps;
  tsetup_d_cp_posedge_posedge      : VitalDelayType := 0 ps;
  tsetup_d_cp_negedge_posedge      : VitalDelayType := 0 ps;
