VARIABLE pw_cp    : std_ulogic := '0';
VARIABLE tpw_cp   : VitalPeriodDataType;


BEGIN
-------------------------
-- Functionality Section 
-------------------------



-- TIMING CHECKS --
IF (TimingChecksOn) THEN
 VitalSetupHoldCheck (
  TestSignal    => sd_dly,
  TestSignalName => "sd",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sd_cp_posedge_posedge,
  SetupLow      => tsetup_sd_cp_negedge_posedge,
  HoldHigh      => thold_sd_cp_negedge_posedge,
  HoldLow       => thold_sd_cp_posedge_posedge,
  CheckEnabled  => (To_X01(sc_dly)='1'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SENRQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sd_cp,
  Violation     => suh_sd_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => sc_dly,
  TestSignalName => "sc",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_sc_cp_posedge_posedge,
  SetupLow      => tsetup_sc_cp_negedge_posedge,
  HoldHigh      => thold_sc_cp_negedge_posedge,
  HoldLow       => thold_sc_cp_posedge_posedge,
  CheckEnabled  => TRUE,
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SENRQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sc_cp,
  Violation     => suh_sc_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => enn_dly,
  TestSignalName => "enn",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_enn_cp_posedge_posedge,
  SetupLow      => tsetup_enn_cp_negedge_posedge,
  HoldHigh      => thold_enn_cp_negedge_posedge,
  HoldLow       => thold_enn_cp_posedge_posedge,
  CheckEnabled  => TRUE,
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SENRQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_enn_cp,
  Violation     => suh_enn_cp
 );
 VitalSetupHoldCheck (
  TestSignal    => d_dly,
  TestSignalName => "d",
  RefSignal     => cp_dly,
  RefSignalName => "cp",
  SetupHigh     => tsetup_d_cp_posedge_posedge,
  SetupLow      => tsetup_d_cp_negedge_posedge,
  HoldHigh      => thold_d_cp_negedge_posedge,
  HoldLow       => thold_d_cp_posedge_posedge,
  CheckEnabled  => (To_X01(enn_dly)='0') and (To_X01(sc_dly)='0'),
  RefTransition => '/',
  HeaderMsg     => InstancePath & " /SENRQ2",
  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_d_cp,
  Violation     => suh_d_cp
 );
 VitalPeriodPulseCheck (
  TestSignal     => cp_dly,
  TestSignalName => "cp",
  PulseWidthHigh => tpw_cp_posedge,
  PulseWidthLow  => tpw_cp_negedge,
  PeriodData     => tpw_cp,
  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /SENRQ2",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => TRUE
  );
END IF;

violation := suh_sd_cp OR suh_sc_cp OR suh_enn_cp OR suh_d_cp OR pw_cp;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (cp_dly,sc_dly,enn_dly,sd_dly,d_dly,violation),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


