  XOn           => XOn,
  MsgOn         => MsgOn,
  TimingData    => tsuh_sdn_cp,
  Violation     => suh_sdn_cp
 );
 VitalPeriodPulseCheck (
  TestSignal     => cp_dly,
  TestSignalName => "cp",
  PulseWidthHigh => tpw_cp_posedge,
  PulseWidthLow  => tpw_cp_negedge,
  PeriodData     => tpw_cp,
  Violation      => pw_cp,
  HeaderMsg      => InstancePath & " /SEPRQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => (To_X01(sdn_dly)='1')
  );
 VitalPeriodPulseCheck (
  TestSignal     => sdn_dly,
  TestSignalName => "sdn",
  PulseWidthLow  => tpw_sdn_negedge,
  PeriodData     => tpw_sdn,
  Violation      => pw_sdn,
  HeaderMsg      => InstancePath & " /SEPRQ1",
  XOn            => XOn,
  MsgOn          => MsgOn,
  CheckEnabled   => TRUE
  );
END IF;

violation := suh_sd_cp OR suh_sc_cp OR suh_enn_cp OR suh_d_cp OR suh_sdn_cp OR pw_cp OR pw_sdn;


VitalStateTable ( StateTable => StateTab,
                      DataIn => (sdn_dly,sc_dly,cp_dly,enn_dly,d_dly,sd_dly,violation),
                   NumStates => 1,
                      Result => Res,
              PreviousDataIn => Prv
              );
--------------------
--Path Delay Section
--------------------
VitalPathDelay01Z (q, q_GlitchData, "q", q_zd,
 Paths=>(0=>(cp_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_cp_q),(To_X01(sdn_dly)/='0')),
 1=>(sdn_dly'LAST_EVENT,VitalExtendToFillDelay(tpd_sdn_q),TRUE)),
 DefaultDelay=>VitalZeroDelay01Z, Mode=>OnDetect, XOn=>XOn, MsgOn=>MsgOn );
END PROCESS;
END behavioral;


