  tsetup_sd_cp_posedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sd_cp_negedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sc_cp_posedge_posedge     : VitalDelayType := 0 ps;
  tsetup_sc_cp_negedge_posedge     : VitalDelayType := 0 ps;
  tsetup_enn_cp_posedge_posedge    : VitalDelayType := 0 ps;
